#include <stdio.h>

typedef enum { GREEN, YELLOW, RED } State;

const char* state_name(State s) {
    switch(s) { case GREEN: return "GREEN"; case YELLOW: return "YELLOW"; case RED: return "RED"; }
    return "";
}

State next_state(State s) {
    switch(s) {
        case GREEN: return YELLOW;
        case YELLOW: return RED;
        case RED: return GREEN;
    }
}

int main() {
    State s = GREEN;
    for (int i = 0; i < 6; i++) {
        printf("State: %s\n", state_name(s));
        s = next_state(s);
    }
    return 0;
}
